// Krylov square-solver battery -- solver x matrix-regime cross-coverage for the square (single-RHS)
// Krylov family, driven through the IdoubleSquareSolverInvoker struct-functor shape (see
// KrylovBattery.Invokers.double.cs). SPIKE: only Krylov.cg (via doubleCgInvoker) is wired so far --
// the de-risking increment for the generic-method-on-a-struct-functor-interface shape this battery is
// built on. Fanning out the rest of the square family (fcg/minres/minresQLP/biCGStab/gmres/fgmres/idr)
// is a later increment; add each as a new SolverKind case + RunStandardChecks call, nothing else in
// this file changes.
//
// Every case runs the same 4 standard checks (SS5.2 #1-4 of the battery spec) across every gallery
// matrix whose tags satisfy the invoker's Requires/Forbids (MatrixProfileMatch.Applicable), plus a
// 5th Sparse-only preconditioned-convergence check on the BSR gallery. Grouped BY SOLVER (one NUnit
// case per SolverKind); the failing (matrix, check, got, expected) is surfaced via Fail.
public class doubleKrylovSquareBatteryTests
{
    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct TestJob : IJob
    {
        public enum SolverKind { Cg }

        public SolverKind Kind;

        // [0] flag (1 = failure recorded) [1] matrix-enum-as-int [2] check-id [3] got [4] expected
        public NativeArray<double> Fail;

        const int DenseCount = (int)GalleryDenseMatrix.RandSPDIllCond20 + 1;
        const int BSRCount = (int)GalleryBSRMatrix.RandomSparseNonsym_80 + 1;

        public void Execute()
        {
            switch (Kind)
            {
                case SolverKind.Cg: RunStandardChecks(new doubleCgInvoker { TolValue = Consts.doubleSqrtEps, MaxIterMul = 20 }); break;
            }
        }

        void RunStandardChecks<TInvoker>(TInvoker inv) where TInvoker : struct, IdoubleSquareSolverInvoker
        {
            for (int i = 0; i < DenseCount; i++)
            {
                var gm = (GalleryDenseMatrix)i;
                if (MatrixProfileMatch.Applicable(inv.Requires, inv.Forbids, GalleryProfiles.Of(gm)))
                    CheckDense(inv, gm);
            }

            for (int i = 0; i < BSRCount; i++)
            {
                var gm = (GalleryBSRMatrix)i;
                if (MatrixProfileMatch.Applicable(inv.Requires, inv.Forbids, GalleryProfiles.Of(gm)))
                    CheckBSR(inv, gm);
            }
        }

        // Checks #1-4 (SS5.2) on one dense literature-gallery matrix.
        void CheckDense<TInvoker>(TInvoker inv, GalleryDenseMatrix gm) where TInvoker : struct, IdoubleSquareSolverInvoker
        {
            var arena = new Arena(Allocator.Persistent);

            var A = doubleKrylovBatteryGallery.Build(ref arena, gm);
            int n = A.M_Rows;
            var Aop = new doubleDenseOperator(in A);
            MatrixProfile tags = GalleryProfiles.Of(gm);
            double tolBand = TolBand(tags);

            var b = arena.doubleRandomVec(n, (double)(-1), (double)1, 0xD000u + (uint)gm);

            inv.Init(ref arena, n);

            // 1. Converges: Solved or MaxIterations, AND the fresh residual bound holds either way.
            var x1 = arena.doubleVec(n);
            SolveInfo info1 = inv.Solve(in Aop, in b, ref x1);
            bool statusOk1 = info1.status == IterativeSolveStatus.Converged || info1.status == IterativeSolveStatus.MaxIterations;
            Record(statusOk1, (int)gm, 1, (double)(int)info1.status, (double)0);
            double relRes1 = doubleKrylovBatteryOracles.RelResidualDense(in A, in x1, in b);
            Record(relRes1 <= (double)10 * inv.Tol, (int)gm, 1, relRes1, (double)10 * inv.Tol);

            // 2. Correctness vs. direct-solve reference (same A, b, and the x1 solved in #1).
            var xRef = ReferenceSolveDense(in A, in b, tags);
            for (int i = 0; i < n; i++)
                Record(math.abs(x1[i] - xRef[i]) <= tolBand * ((double)1 + math.abs(xRef[i])), (int)gm, 2, x1[i], xRef[i]);

            // 3. Determinism: two independent solves from x0=0 on the identical (A, b) match bit-for-bit.
            var x3a = arena.doubleVec(n);
            var x3b = arena.doubleVec(n);
            SolveInfo info3a = inv.Solve(in Aop, in b, ref x3a);
            SolveInfo info3b = inv.Solve(in Aop, in b, ref x3b);
            for (int i = 0; i < n; i++)
                Record(x3a[i] == x3b[i], (int)gm, 3, x3a[i], x3b[i]);
            Record(info3a.iterations == info3b.iterations, (int)gm, 3, (double)info3a.iterations, (double)info3b.iterations);

            // 4. Identity-fold: the unpreconditioned path == the generic path with an explicit identity.
            var x4a = arena.doubleVec(n);
            var x4b = arena.doubleVec(n);
            SolveInfo info4a = inv.Solve(in Aop, in b, ref x4a);
            SolveInfo info4b = inv.SolveWithPrecond(in Aop, default(doubleIdentityPreconditioner), in b, ref x4b);
            for (int i = 0; i < n; i++)
                Record(x4a[i] == x4b[i], (int)gm, 4, x4a[i], x4b[i]);
            Record(info4a.iterations == info4b.iterations, (int)gm, 4, (double)info4a.iterations, (double)info4b.iterations);

            arena.Dispose();
        }

        // Checks #1-5 (SS5.2) on one BSR gallery matrix -- #5 (preconditioned convergence) always
        // applies here since every BSR gallery entry carries the Sparse tag.
        void CheckBSR<TInvoker>(TInvoker inv, GalleryBSRMatrix gm) where TInvoker : struct, IdoubleSquareSolverInvoker
        {
            var arena = new Arena(Allocator.Persistent);

            var A = doubleKrylovBatteryGallery.Build(ref arena, gm);
            int n = A.M_Rows;
            var Aop = new doubleBSROperator(in A);
            MatrixProfile tags = GalleryProfiles.Of(gm);
            double tolBand = TolBand(tags);

            var b = arena.doubleRandomVec(n, (double)(-1), (double)1, 0xB000u + (uint)gm);

            inv.Init(ref arena, n);

            // 1. Converges.
            var x1 = arena.doubleVec(n);
            SolveInfo info1 = inv.Solve(in Aop, in b, ref x1);
            bool statusOk1 = info1.status == IterativeSolveStatus.Converged || info1.status == IterativeSolveStatus.MaxIterations;
            Record(statusOk1, (int)gm, 1, (double)(int)info1.status, (double)0);
            double relRes1 = doubleKrylovBatteryOracles.RelResidualBSR(in A, in x1, in b);
            Record(relRes1 <= (double)10 * inv.Tol, (int)gm, 1, relRes1, (double)10 * inv.Tol);

            // 2. Correctness vs. direct-solve reference (densify A -- no direct BSR factorization).
            var Adense = A.ToDense(ref arena);
            var xRef = ReferenceSolveDense(in Adense, in b, tags);
            for (int i = 0; i < n; i++)
                Record(math.abs(x1[i] - xRef[i]) <= tolBand * ((double)1 + math.abs(xRef[i])), (int)gm, 2, x1[i], xRef[i]);

            // 3. Determinism.
            var x3a = arena.doubleVec(n);
            var x3b = arena.doubleVec(n);
            SolveInfo info3a = inv.Solve(in Aop, in b, ref x3a);
            SolveInfo info3b = inv.Solve(in Aop, in b, ref x3b);
            for (int i = 0; i < n; i++)
                Record(x3a[i] == x3b[i], (int)gm, 3, x3a[i], x3b[i]);
            Record(info3a.iterations == info3b.iterations, (int)gm, 3, (double)info3a.iterations, (double)info3b.iterations);

            // 4. Identity-fold.
            var x4a = arena.doubleVec(n);
            var x4b = arena.doubleVec(n);
            SolveInfo info4a = inv.Solve(in Aop, in b, ref x4a);
            SolveInfo info4b = inv.SolveWithPrecond(in Aop, default(doubleIdentityPreconditioner), in b, ref x4b);
            for (int i = 0; i < n; i++)
                Record(x4a[i] == x4b[i], (int)gm, 4, x4a[i], x4b[i]);
            Record(info4a.iterations == info4b.iterations, (int)gm, 4, (double)info4a.iterations, (double)info4b.iterations);

            // 5. Preconditioned convergence (Sparse-only), M built per inv.PrecondKind.
            var x5 = arena.doubleVec(n);
            SolveInfo info5;
            if (inv.PrecondKind == PreconditionerKind.SymmetricBSR)
            {
                var M = arena.doubleBlockJacobi(in A);
                info5 = inv.SolveWithPrecond(in Aop, in M, in b, ref x5);
            }
            else if (inv.PrecondKind == PreconditionerKind.NonsymmetricBSR)
            {
                var M = arena.doubleILU0(in A);
                info5 = inv.SolveWithPrecond(in Aop, in M, in b, ref x5);
            }
            else
            {
                info5 = inv.Solve(in Aop, in b, ref x5);
            }
            bool statusOk5 = info5.status == IterativeSolveStatus.Converged || info5.status == IterativeSolveStatus.MaxIterations;
            Record(statusOk5, (int)gm, 5, (double)(int)info5.status, (double)0);
            double relRes5 = doubleKrylovBatteryOracles.RelResidualBSR(in A, in x5, in b);
            Record(relRes5 <= (double)10 * inv.Tol, (int)gm, 5, relRes5, (double)10 * inv.Tol);

            arena.Dispose();
        }

        // Reference solution via the library's own direct solver for A's KIND: CHO for SPD,
        // LU for SymmetricIndefinite/Nonsymmetric.
        doubleN ReferenceSolveDense(in doubleMxN A, in doubleN b, MatrixProfile tags)
        {
            var xRef = b.Copy();
            if ((tags & MatrixProfile.SPD) != 0)
            {
                var L = A.Copy();
                CHO.decompInPlace(ref L);
                CHO.decompSolve(ref L, ref xRef);
            }
            else
            {
                var LUm = A.Copy();
                var P = new Pivot(A.M_Rows, Allocator.Temp);
                LU.decompInPlace(ref LUm, ref P);
                LU.decompSolve(ref LUm, in P, ref xRef);
                P.Dispose();
            }
            return xRef;
        }

        // WellConditioned -> 50*sqrtEps, IllConditioned -> 5E-2 (mirrors SolverBatteryTests' hardcoded
        // per-matrix bands; not a live Analysis.cond() call, to keep the battery cheap).
        static double TolBand(MatrixProfile tags)
            => (tags & MatrixProfile.IllConditioned) != 0 ? (double)5E-2 : (double)50 * Consts.doubleSqrtEps;

        void Record(bool ok, int matrixIdx, int checkId, double got, double expected)
        {
            if (!ok && Fail[0] == (double)0)
            {
                Fail[0] = (double)1;
                Fail[1] = (double)matrixIdx;
                Fail[2] = (double)checkId;
                Fail[3] = got;
                Fail[4] = expected;
            }
            Assert.IsTrue(ok);
        }
    }

    static Array GetKinds() => Enum.GetValues(typeof(TestJob.SolverKind));

